import React, { useCallback, useEffect, useState } from 'react';
import { Alert, Box, Button, Chip, Paper, Skeleton, Stack, Typography } from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';

export interface FactorExceptionQueueRow {
  exceptionId: string;
  exceptionType: string;
  severity?: string;
  status?: string;
  reason?: string;
  message?: string;
  detectedAt?: string;
  transactionId: string;
  msmeId: string;
  description?: string;
  companyName?: string;
  blocksReport?: boolean;
}

const ExpertFactorExceptionQueue: React.FC<{
  onOpen: (row: FactorExceptionQueueRow) => void;
}> = ({ onOpen }) => {
  const [rows, setRows] = useState<FactorExceptionQueueRow[]>([]);
  const [cursor, setCursor] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [partial, setPartial] = useState(false);

  const load = useCallback(async (append: boolean, nextCursor?: string | null) => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(buildApiUrl('/expert/factor-exceptions'), {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
        params: { limit: 25, cursor: nextCursor || undefined },
      });
      const page: FactorExceptionQueueRow[] = response.data?.data?.exceptions || [];
      setRows((current) => {
        if (!append) return page;
        const seen = new Set(current.map((row) => row.exceptionId));
        return [...current, ...page.filter((row) => !seen.has(row.exceptionId))];
      });
      const more = response.data?.data?.nextCursor || null;
      setCursor(more);
      setPartial(response.data?.data?.totalsScope === 'loaded_page' || Boolean(more));
    } catch (loadError: any) {
      setError(loadError?.response?.data?.message || 'Factor exceptions could not be loaded.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load(false);
  }, [load]);

  return (
    <Stack spacing={2}>
      {partial ? (
        <Typography variant="caption" color="text.secondary">More exceptions remain on the server.</Typography>
      ) : null}
      {error ? (
        <Alert severity="error" action={<Button color="inherit" size="small" onClick={() => void load(false)}>Retry</Button>}>
          {error}
        </Alert>
      ) : null}
      {loading && rows.length === 0 ? (
        <Stack spacing={1} aria-label="Loading factor exceptions">
          {[0, 1, 2].map((key) => <Skeleton key={key} variant="rounded" height={88} />)}
        </Stack>
      ) : null}
      {!loading && rows.length === 0 ? <Typography variant="body2">No open factor exceptions.</Typography> : null}
      {rows.map((row) => (
        <Paper key={row.exceptionId} variant="outlined" sx={{ p: 2 }}>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5} justifyContent="space-between" alignItems={{ sm: 'center' }}>
            <Stack spacing={0.5} sx={{ minWidth: 0, flex: 1 }}>
              <Stack direction="row" spacing={1} alignItems="center">
                <Box
                  aria-hidden
                  sx={{
                    width: 10,
                    height: 10,
                    borderRadius: '50%',
                    flexShrink: 0,
                    bgcolor: row.blocksReport || row.severity === 'high' ? 'error.main' : row.severity === 'low' ? 'success.main' : 'warning.main',
                  }}
                />
                <Typography variant="subtitle1" sx={{ fontWeight: 700, minWidth: 0 }}>
                  {row.companyName || 'Company name unavailable'}
                </Typography>
              </Stack>
              <Typography variant="body2">{row.description || row.transactionId}</Typography>
              <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
                <Chip size="small" label={row.exceptionType} />
                <Chip size="small" variant="outlined" label={row.severity || 'unspecified'} />
                <Chip size="small" variant="outlined" label={row.status || 'open'} />
              </Stack>
              <Typography variant="caption" color="text.secondary">
                {row.detectedAt ? new Date(row.detectedAt).toLocaleString() : 'Detected date unavailable'}
              </Typography>
              <Typography variant="body2">{row.reason || row.message || 'No reason was stored.'}</Typography>
            </Stack>
            <Button variant="contained" sx={{ alignSelf: { xs: 'stretch', sm: 'center' }, flexShrink: 0 }} onClick={() => onOpen(row)} disabled={!row.transactionId || !row.msmeId}>
              Open transaction
            </Button>
          </Stack>
        </Paper>
      ))}
      {cursor ? (
        <Button onClick={() => void load(true, cursor)} disabled={loading}>Load more exceptions</Button>
      ) : null}
    </Stack>
  );
};

export default ExpertFactorExceptionQueue;
