import React, { useCallback, useEffect, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import ExpertPortalLayout, { ExpertSection } from './ExpertPortalLayout';
import ExpertCalculationReview from './ExpertCalculationReview';
import ExpertUserList, { ConsultantUserRow } from './ExpertUserList';
import ExpertSubmissionQueue from './ExpertSubmissionQueue';
import ExpertOverview, { OverviewSubmission } from './ExpertOverview';
import ExpertEmissionReview from './ExpertEmissionReview';
import ExpertFactorExceptionQueue from './ExpertFactorExceptionQueue';

const SECTIONS: ExpertSection[] = ['overview', 'queue', 'companies', 'review', 'exceptions', 'classification'];

const ExpertDashboard: React.FC = () => {
  const [params, setParams] = useSearchParams();
  const requested = params.get('section') || 'overview';
  const section: ExpertSection = SECTIONS.includes(requested as ExpertSection) ? requested as ExpertSection : 'overview';
  const userId = params.get('user') || '';
  const [users, setUsers] = useState<ConsultantUserRow[]>([]);
  const [submissions, setSubmissions] = useState<OverviewSubmission[]>([]);
  const [submissionsComplete, setSubmissionsComplete] = useState(true);
  const [companyTotalsScope, setCompanyTotalsScope] = useState<'loaded_page' | 'complete'>('loaded_page');
  const [overviewError, setOverviewError] = useState<string | null>(null);
  const [overviewLoading, setOverviewLoading] = useState(true);
  const [picked, setPicked] = useState<ConsultantUserRow | null>(null);

  const loadOverview = useCallback(async () => {
    const headers = { Authorization: `Bearer ${localStorage.getItem('token')}` };
    setOverviewLoading(true);
    try {
      const [userResponse, submissionResponse] = await Promise.all([
        axios.get(buildApiUrl('/expert/users'), { headers }),
        axios.get(buildApiUrl('/expert/submissions'), { headers, params: { limit: 20 } }),
      ]);
      setUsers(userResponse.data?.data?.users || []);
      setCompanyTotalsScope(userResponse.data?.data?.totalsScope === 'complete' ? 'complete' : 'loaded_page');
      setSubmissions(submissionResponse.data?.data?.submissions || []);
      setSubmissionsComplete(submissionResponse.data?.data?.totalsScope === 'complete' && !submissionResponse.data?.data?.nextCursor);
      setOverviewError(null);
    } catch (loadError: any) {
      setUsers([]);
      setSubmissions([]);
      setCompanyTotalsScope('loaded_page');
      setSubmissionsComplete(false);
      setOverviewError(loadError?.response?.data?.message || 'The overview could not be loaded.');
    } finally {
      setOverviewLoading(false);
    }
  }, []);

  useEffect(() => {
    void loadOverview();
  }, [loadOverview]);

  const go = (next: ExpertSection, user?: string, msme?: string) => {
    const nextParams: Record<string, string> = { section: next };
    if (user) nextParams.user = user;
    else if (next === 'review' && userId) nextParams.user = userId;
    if (msme) nextParams.msme = msme;
    else if (next === 'review' && params.get('msme')) nextParams.msme = params.get('msme') || '';
    setParams(nextParams);
  };

  const selected = users.find((user) => user.userId === userId) || (picked && picked.userId === userId ? picked : null);
  const companyNames = Object.fromEntries(users.filter((user) => user.msmeId).map((user) => [user.msmeId, user.companyName || user.name]));

  const title = {
    overview: 'Overview',
    queue: 'Review queue',
    companies: 'Companies',
    review: selected ? (selected.companyName || selected.name) : 'Calculation review',
    exceptions: 'Factor exceptions',
    classification: 'Activity classification',
  }[section];

  const subtitle = {
    overview: 'Open work across the companies and submissions you review.',
    queue: 'Each row is one company submission. Open it to see the transactions, then approve only the rows the server still accepts.',
    companies: 'Choose a company user. Counts on this page are the full counts for those companies.',
    review: 'Uncertain and clarification desk.',
    exceptions: 'Open factor exceptions that can block an official report. Resolving an exception does not approve the row.',
    classification: 'Classify held activities. The list uses one order, and further pages stay on the server until you load them.',
  }[section];

  const breadcrumbs = section === 'review'
    ? [
      { label: 'Companies', onClick: () => go('companies') },
      { label: selected?.companyName || selected?.name || 'Review' },
    ]
    : [{ label: 'Expert' }, { label: title }];

  return (
    <ExpertPortalLayout title={title} subtitle={subtitle} section={section} onSection={(next) => go(next)} breadcrumbs={breadcrumbs}>
      {section === 'overview' ? (
        <ExpertOverview
          users={users}
          submissions={submissions}
          submissionsComplete={submissionsComplete}
          companyTotalsScope={companyTotalsScope}
          error={overviewError}
          loading={overviewLoading}
          onRetry={() => { void loadOverview(); }}
          onSection={(next) => go(next)}
          onReview={(user) => { setPicked(user); go('review', user.userId, user.msmeId); }}
        />
      ) : null}
      {section === 'exceptions' ? (
        <ExpertFactorExceptionQueue
          onOpen={(row) => {
            const nextParams: Record<string, string> = {
              section: 'review',
              msme: row.msmeId,
              tx: row.transactionId,
            };
            setParams(nextParams);
          }}
        />
      ) : null}
      {section === 'queue' ? <ExpertSubmissionQueue companyNames={companyNames} /> : null}
      {section === 'companies' ? (
        <ExpertUserList onSelect={(user) => { setPicked(user); go('review', user.userId, user.msmeId); }} />
      ) : null}
      {section === 'review' ? (
        <ExpertCalculationReview
          selectedUser={selected || undefined}
          companyId={params.get('msme') || ''}
          focusTransactionId={params.get('tx') || ''}
          chooseCompany={!userId && !params.get('msme')}
          onBack={() => go('companies')}
        />
      ) : null}
      {section === 'classification' ? <ExpertEmissionReview /> : null}
    </ExpertPortalLayout>
  );
};

export default ExpertDashboard;
