const {
  DEFAULT_SCOPE3_CATEGORIES_INCLUDED,
  GHG_SCOPE3_CATEGORY_OPTIONS
} = require('./ghgBoundaryBrsr');

/** Scope 3 categories that start outside the usual MSME value chain. */
const OPTIONAL_SCOPE3_CATEGORIES = Object.freeze([8, 10, 11, 12, 13, 14, 15]);

const OPTIONAL_SCOPE3_SHORT = Object.freeze({
  8: 'Leased assets in',
  10: 'Customer processing',
  11: 'Product use',
  12: 'End of life',
  13: 'Leased assets out',
  14: 'Franchises',
  15: 'Investments'
});

const OPTIONAL_SCOPE3_KEY = Object.freeze({
  8: 'cat8_upstream_leased_assets',
  10: 'cat10_processing_sold_products',
  11: 'cat11_use_sold_products',
  12: 'cat12_end_of_life',
  13: 'cat13_downstream_leased_assets',
  14: 'cat14_franchises',
  15: 'cat15_investments'
});

const OUTSIDE_NOTE_PREFIX = 'Categories left outside the value chain:';
const ALL_INSIDE_NOTE = 'None. Categories 8, 10, 11, 12, 13, 14, and 15 are inside the value chain.';

const toCategoryNumbers = (value) => {
  if (!Array.isArray(value)) return [];
  return [...new Set(
    value
      .map((entry) => Number(entry))
      .filter((entry) => Number.isInteger(entry) && entry >= 1 && entry <= 15)
  )].sort((left, right) => left - right);
};

const storedOrUsualCategories = (value) => {
  const stored = toCategoryNumbers(value);
  if (stored.length > 0) return stored;
  return [...DEFAULT_SCOPE3_CATEGORIES_INCLUDED];
};

const optionLabel = (value) => (
  GHG_SCOPE3_CATEGORY_OPTIONS.find((option) => option.value === value)?.label
  || `Category ${value}`
);

const outsideNote = (remaining) => {
  if (!remaining.length) return ALL_INSIDE_NOTE;
  const names = remaining.map((value) => `${value} — ${OPTIONAL_SCOPE3_SHORT[value]}`).join('; ');
  return `${OUTSIDE_NOTE_PREFIX} ${names}.`;
};

const noteIsGenerated = (note) => {
  const text = String(note || '').trim();
  return !text || text === ALL_INSIDE_NOTE || text.startsWith(OUTSIDE_NOTE_PREFIX);
};

const scope3BoundaryView = (boundary = {}) => {
  const included = storedOrUsualCategories(boundary.scope3CategoriesIncluded);
  const includedSet = new Set(included);
  return {
    scope3CategoriesIncluded: included,
    scope3OutOfBoundarySummary: String(boundary.scope3OutOfBoundarySummary || ''),
    options: OPTIONAL_SCOPE3_CATEGORIES.map((value) => ({
      value,
      label: optionLabel(value),
      short: OPTIONAL_SCOPE3_SHORT[value],
      included: includedSet.has(value)
    }))
  };
};

/**
 * Turn the optional categories on or off without dropping the categories the
 * company already keeps (the usual 1–7 and 9, or a shorter saved list).
 */
const parseOptionalScope3Category = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const number = Number(value);
  return OPTIONAL_SCOPE3_CATEGORIES.includes(number) ? number : null;
};

const includeOptionalScope3Category = (boundary = {}, categoryNumber) => {
  const number = parseOptionalScope3Category(categoryNumber);
  if (!number) return null;
  const current = storedOrUsualCategories(boundary.scope3CategoriesIncluded);
  const already = current.filter((value) => OPTIONAL_SCOPE3_CATEGORIES.includes(value));
  return applyOptionalScope3Categories(boundary, [...already, number]);
};

/**
 * The expert's link names where the Scope 3 kilograms are reported.
 * Scope 1 and Scope 2 on the same voucher stay as calculated.
 */
const applyConsultantScope3Link = (footprint = {}, categoryNumber) => {
  const number = parseOptionalScope3Category(categoryNumber);
  if (!number) return footprint;
  const key = OPTIONAL_SCOPE3_KEY[number];
  footprint.ghgScope3Category = key;
  footprint.ghgScope3CategoryNumber = number;
  const scope3 = Number(footprint.emissionBreakdown?.scope3) || 0;
  if (scope3 > 0) {
    footprint.scope3Components = [{
      ghgScope3Category: key,
      kg: scope3,
      label: OPTIONAL_SCOPE3_SHORT[number]
    }];
  }
  if (footprint.scopeClassification && typeof footprint.scopeClassification === 'object') {
    footprint.scopeClassification.scope3Category = number;
  }
  return footprint;
};

const applyOptionalScope3Categories = (boundary = {}, include = []) => {
  const current = storedOrUsualCategories(boundary.scope3CategoriesIncluded);
  const wanted = new Set(
    toCategoryNumbers(include).filter((value) => OPTIONAL_SCOPE3_CATEGORIES.includes(value))
  );
  const next = current.filter((value) => (
    !OPTIONAL_SCOPE3_CATEGORIES.includes(value) || wanted.has(value)
  ));
  OPTIONAL_SCOPE3_CATEGORIES.forEach((value) => {
    if (wanted.has(value) && !next.includes(value)) next.push(value);
  });
  next.sort((left, right) => left - right);
  const remaining = OPTIONAL_SCOPE3_CATEGORIES.filter((value) => !next.includes(value));
  const previous = String(boundary.scope3OutOfBoundarySummary || '');
  const keptCompanyNote = !noteIsGenerated(previous);
  return {
    scope3CategoriesIncluded: next,
    scope3OutOfBoundarySummary: keptCompanyNote ? previous.trim() : outsideNote(remaining),
    keptCompanyNote
  };
};

const consultantLinkedScope3Key = (transaction = {}) => {
  const number = parseOptionalScope3Category(
    transaction.metadata?.consultantScope3Category
    ?? transaction.carbonFootprint?.ghgScope3CategoryNumber
  );
  return number ? OPTIONAL_SCOPE3_KEY[number] : '';
};

