const scope3LinkGuidance = (categoryNumber) => {
  const number = parseOptionalScope3Category(categoryNumber);
  if (!number) return null;
  const detail = LINK_GUIDANCE[number];
  return {
    category: number,
    key: OPTIONAL_SCOPE3_KEY[number],
    short: OPTIONAL_SCOPE3_SHORT[number],
    label: optionLabel(number),
    unit: detail.unit,
    transaction: detail.transaction,
    profile: detail.profile,
    other: detail.other
  };
};

module.exports = {
  OPTIONAL_SCOPE3_CATEGORIES,
  OPTIONAL_SCOPE3_SHORT,
  ALL_INSIDE_NOTE,
  OUTSIDE_NOTE_PREFIX,
  scope3BoundaryView,
  applyOptionalScope3Categories,
  parseOptionalScope3Category,
  includeOptionalScope3Category,
  applyConsultantScope3Link,
  OPTIONAL_SCOPE3_KEY,
  consultantLinkedScope3Key,
  scope3LinkGuidance
};
