import React from 'react';
import { Alert, Box, Button, Card, CardActionArea, CardContent, Chip, Skeleton, Stack, Typography } from '@mui/material';
import { ConsultantUserRow } from './ExpertUserList';
import { ExpertSection } from './ExpertPortalLayout';

interface SubmissionCounts {
  total?: number;
  approved?: number;
  pending?: number;
  processing?: number;
  waitingForBill?: number;
  additionalInformation?: number;
  failed?: number;
  reviewable?: number;
  bulkApproval?: { eligible?: number };
}

export interface OverviewSubmission {
  batchId: string;
  msmeId: string;
  status: string;
  source: string;
  fileName?: string;
  counts?: SubmissionCounts;
}

interface ExpertOverviewProps {
  users: ConsultantUserRow[];
  submissions: OverviewSubmission[];
  submissionsComplete: boolean;
  companyTotalsScope: 'loaded_page' | 'complete';
  error?: string | null;
  loading?: boolean;
  onRetry?: () => void;
  onSection: (section: ExpertSection) => void;
  onReview: (user: ConsultantUserRow) => void;
}

const sum = (rows: OverviewSubmission[], key: keyof SubmissionCounts) => (
  rows.reduce((total, row) => total + Number(row.counts?.[key] || 0), 0)
);

const statusDot = (status: string) => {
  const value = status.toLowerCase();
  if (value.includes('fail')) return 'error.main';
  if (value.includes('approv')) return 'success.main';
  if (value.includes('partial') || value.includes('information') || value.includes('bill') || value.includes('pending')) return 'warning.main';
  return 'text.disabled';
};

const ExpertOverview: React.FC<ExpertOverviewProps> = ({
  users,
  submissions,
  companyTotalsScope,
  error,
  loading = false,
  onRetry,
  onSection,
  onReview,
}) => {
  const openUsers = users.filter((user) => user.msmeId && user.openRequired > 0);
  const companyName = (msmeId: string) => (
    users.find((user) => user.msmeId === msmeId)?.companyName || 'Company name unavailable'
  );

  const cards = [
    {
      label: 'Companies with open rows',
      value: openUsers.length,
      hint: companyTotalsScope === 'complete' ? 'All companies in this view' : 'Companies loaded on this page',
    },
    {
      label: 'Eligible for bulk approval',
      value: submissions.reduce((total, row) => total + Number(row.counts?.bulkApproval?.eligible || 0), 0),
      hint: 'Rows a submission can send',
    },
    { label: 'Clarification open', value: sum(submissions, 'additionalInformation'), hint: 'Waiting on the company' },
    { label: 'Bill required', value: sum(submissions, 'waitingForBill'), hint: 'Needs a bill' },
    { label: 'Calculation failed', value: sum(submissions, 'failed'), hint: 'Needs a correction' },
    { label: 'Approved in submissions', value: sum(submissions, 'approved'), hint: 'Already confirmed' },
  ];

  return (
    <Stack spacing={3}>
      {error ? <Alert severity="error" action={onRetry ? <Button color="inherit" size="small" onClick={onRetry}>Retry</Button> : undefined}>{error}</Alert> : null}
      <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr', lg: 'repeat(3, 1fr)' }, gap: 2 }}>
        {loading ? cards.map((card) => (
          <Skeleton key={card.label} variant="rounded" height={96} />
        )) : cards.map((card) => (
          <Card key={card.label} variant="outlined">
            <CardContent>
              <Typography variant="body2" color="text.secondary">{card.label}</Typography>
              <Typography variant="h4" sx={{ fontWeight: 700 }}>{card.value}</Typography>
              <Typography variant="caption" color="text.secondary">{card.hint}</Typography>
            </CardContent>
          </Card>
        ))}
      </Box>

      <Box>
        <Stack direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" alignItems={{ xs: 'flex-start', sm: 'center' }} spacing={1} sx={{ mb: 1 }}>
          <Typography variant="h6" component="h2">Recent submissions</Typography>
          <Button size="small" onClick={() => onSection('queue')}>Open queue</Button>
        </Stack>
        {loading ? (
          <Stack spacing={1}>
            {[0, 1].map((key) => <Skeleton key={key} variant="rounded" height={72} />)}
          </Stack>
        ) : submissions.length === 0 ? (
          <Typography variant="body2">No stamped submissions were returned.</Typography>
        ) : (
          <Stack spacing={1}>
            {submissions.slice(0, 4).map((row) => {
              const eligible = row.counts?.bulkApproval?.eligible;
              const source = row.source === 'connector' ? 'Data Connector' : 'Excel';
              return (
                <Card key={`${row.msmeId}-${row.batchId}`} variant="outlined">
                  <CardActionArea onClick={() => onSection('queue')}>
                    <CardContent sx={{ display: 'flex', gap: 2, alignItems: 'center', flexWrap: 'wrap', py: 1.5, '&:last-child': { pb: 1.5 } }}>
                      <Box aria-hidden sx={{ width: 10, height: 10, borderRadius: '50%', bgcolor: statusDot(row.status), flexShrink: 0 }} />
                      <Box sx={{ flex: 1, minWidth: 0 }}>
                        <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>{companyName(row.msmeId)}</Typography>
                        <Typography variant="body2" color="text.secondary" noWrap>
                          {eligible == null ? source : `${source} · ${eligible} eligible`}
                        </Typography>
                      </Box>
                      <Chip size="small" variant="outlined" label={row.status} />
                    </CardContent>
                  </CardActionArea>
                </Card>
              );
            })}
          </Stack>
        )}
      </Box>

      <Box>
        <Stack direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" alignItems={{ xs: 'flex-start', sm: 'center' }} spacing={1} sx={{ mb: 1 }}>
          <Typography variant="h6" component="h2">Next reviews</Typography>
          <Button size="small" onClick={() => onSection('companies')}>All companies</Button>
        </Stack>
        {loading ? (
          <Stack spacing={1}>
            {[0, 1].map((key) => <Skeleton key={key} variant="rounded" height={72} />)}
          </Stack>
        ) : openUsers.length === 0 ? (
          <Typography variant="body2">
            {companyTotalsScope === 'complete'
              ? 'No company has open uncertain rows.'
              : 'No company on this page has open uncertain rows.'}
          </Typography>
        ) : (
          <Stack spacing={1}>
            {openUsers.slice(0, 5).map((user) => (
              <Card key={user.userId} variant="outlined">
                <CardContent sx={{ display: 'flex', gap: 2, alignItems: 'center', flexWrap: 'wrap', py: 1.5, '&:last-child': { pb: 1.5 } }}>
                  <Box aria-hidden sx={{ width: 10, height: 10, borderRadius: '50%', bgcolor: 'error.main', flexShrink: 0 }} />
                  <Box sx={{ flex: 1, minWidth: 0 }}>
                    <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>{user.companyName || user.name}</Typography>
                    <Typography variant="body2" color="text.secondary">
                      {`${user.name} · ${user.openRequired} open`}
                    </Typography>
                  </Box>
                  <Button variant="contained" size="small" sx={{ maxWidth: '100%' }} onClick={() => onReview(user)}>{`Review ${user.name}`}</Button>
                </CardContent>
              </Card>
            ))}
          </Stack>
        )}
      </Box>
    </Stack>
  );
};

export default ExpertOverview;
