import React, { useState } from 'react';
import {
  AppBar,
  Box,
  Button,
  Chip,
  Drawer,
  IconButton,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Stack,
  Toolbar,
  Typography,
  useMediaQuery,
  useTheme,
} from '@mui/material';
import {
  Dashboard as OverviewIcon,
  FactCheck as ReviewIcon,
  Inbox as QueueIcon,
  Tune as ClassIcon,
  WarningAmber as ExceptionIcon,
  Logout as LogoutIcon,
  Menu as MenuIcon,
  Apartment as CompaniesIcon,
  DarkMode as DarkModeIcon,
  LightMode as LightModeIcon,
} from '@mui/icons-material';
import { useThemeMode } from '../../context/ThemeModeContext';
import { getPortalRoleLabel } from '../../constants/adminPortal';
import { SIDEBAR_WIDTH } from '../../constants/appNavigation';
import { APP_CONTENT_GUTTER } from '../../constants/appShellLayout';
import { getAdminPortalUser } from '../../utils/adminPortalSession';
import { useRegistration } from '../../context/RegistrationContext';
import {
  SIDEBAR_WORKSPACE_BACKGROUND,
  SIDEBAR_WORKSPACE_BORDER,
  SIDEBAR_WORKSPACE_TEXT_PRIMARY,
  SIDEBAR_WORKSPACE_TEXT_SECONDARY,
} from '../../theme';

export type ExpertSection = 'overview' | 'queue' | 'companies' | 'review' | 'exceptions' | 'classification';

const NAV: { id: ExpertSection; label: string; hint?: string; icon: React.ReactNode }[] = [
  { id: 'overview', label: 'Overview', icon: <OverviewIcon fontSize="small" /> },
  { id: 'queue', label: 'Review queue', icon: <QueueIcon fontSize="small" /> },
  { id: 'exceptions', label: 'Factor exceptions', icon: <ExceptionIcon fontSize="small" /> },
  { id: 'companies', label: 'Companies', icon: <CompaniesIcon fontSize="small" /> },
  { id: 'review', label: 'Calculation review', hint: 'Uncertain and clarification', icon: <ReviewIcon fontSize="small" /> },
  { id: 'classification', label: 'Activity classification', icon: <ClassIcon fontSize="small" /> },
];

export interface ExpertCrumb {
  label: string;
  onClick?: () => void;
}

interface ExpertPortalLayoutProps {
  title: string;
  subtitle?: string;
  section: ExpertSection;
  onSection: (section: ExpertSection) => void;
  breadcrumbs?: ExpertCrumb[];
  children: React.ReactNode;
}

const ExpertPortalLayout: React.FC<ExpertPortalLayoutProps> = ({
  title,
  subtitle,
  section,
  onSection,
  breadcrumbs = [],
  children,
}) => {
  const theme = useTheme();
  const isDesktop = useMediaQuery(theme.breakpoints.up('md'));
  const { isDarkMode, toggleThemeMode } = useThemeMode();
  const [mobileOpen, setMobileOpen] = useState(false);
  const { logout } = useRegistration();
  const portalUser = getAdminPortalUser();
  const displayName = [portalUser?.profile?.firstName, portalUser?.profile?.lastName]
    .filter(Boolean)
    .join(' ')
    .trim();

  const go = (next: ExpertSection) => {
    onSection(next);
    setMobileOpen(false);
  };

  const sidebar = (
    <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <Box sx={{ px: 2.5, py: 2 }}>
        <Typography variant="subtitle1" sx={{ fontWeight: 800, letterSpacing: 0.4, color: SIDEBAR_WORKSPACE_TEXT_PRIMARY }}>
          CIMSME
        </Typography>
        <Typography variant="overline" sx={{ display: 'block', color: SIDEBAR_WORKSPACE_TEXT_SECONDARY, letterSpacing: 1.2, lineHeight: 1.4 }}>
          Expert workspace
        </Typography>
      </Box>
      <List sx={{ px: 1, flex: 1 }}>
        {NAV.map((item) => {
          const active = section === item.id;
          return (
            <ListItemButton
              key={item.id}
              selected={active}
              aria-current={active ? 'page' : undefined}
              onClick={() => go(item.id)}
              sx={{
                mb: 0.5,
                borderRadius: 1,
                color: active ? '#fff' : SIDEBAR_WORKSPACE_TEXT_PRIMARY,
                backgroundColor: active ? 'rgba(76, 175, 80, 0.28)' : 'transparent',
                '&:hover': { backgroundColor: active ? 'rgba(76, 175, 80, 0.34)' : 'rgba(255, 255, 255, 0.06)' },
                '&:focus-visible': { outline: '2px solid #ffffff', outlineOffset: 2 },
              }}
            >
              <ListItemIcon sx={{ minWidth: 36, color: 'inherit' }}>{item.icon}</ListItemIcon>
              <ListItemText
                primary={item.label}
                secondary={item.hint}
                primaryTypographyProps={{ fontSize: 14, fontWeight: active ? 700 : 500 }}
                secondaryTypographyProps={{ fontSize: 11, color: active ? 'rgba(255,255,255,0.8)' : SIDEBAR_WORKSPACE_TEXT_SECONDARY }}
              />
            </ListItemButton>
          );
        })}
      </List>
    </Box>
  );

  return (
    <Box sx={{ display: 'flex', position: 'absolute', inset: 0, minHeight: 0, overflow: 'hidden', bgcolor: 'background.default' }}>
      <Drawer
        variant={isDesktop ? 'permanent' : 'temporary'}
        open={isDesktop || mobileOpen}
        onClose={() => setMobileOpen(false)}
        ModalProps={{ keepMounted: true }}
        sx={{
          width: isDesktop ? SIDEBAR_WIDTH : 0,
          flexShrink: 0,
          '& .MuiDrawer-paper': {
            width: SIDEBAR_WIDTH,
            boxSizing: 'border-box',
            bgcolor: SIDEBAR_WORKSPACE_BACKGROUND,
            color: SIDEBAR_WORKSPACE_TEXT_PRIMARY,
            borderRight: `1px solid ${SIDEBAR_WORKSPACE_BORDER}`,
          },
        }}
      >
        {sidebar}
      </Drawer>
      <Box sx={{ flex: 1, minWidth: 0, minHeight: 0, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
        <AppBar position="static" color="default" elevation={0} sx={{ borderBottom: 1, borderColor: 'divider', bgcolor: 'background.paper' }}>
          <Toolbar sx={{ gap: 1, flexWrap: 'wrap', py: 1 }}>
            {isDesktop ? null : (
              <IconButton aria-label="Open navigation" edge="start" onClick={() => setMobileOpen(true)}>
                <MenuIcon />
              </IconButton>
            )}
            <Box sx={{ flexGrow: 1, minWidth: 160 }}>
              <Typography variant="body2" sx={{ fontWeight: 700 }}>
                {displayName || portalUser?.email || 'Expert consultant'}
              </Typography>
            </Box>
            <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap>
              <Chip size="small" color="primary" label={getPortalRoleLabel(portalUser?.role)} />
              <Button
                size="small"
                color="inherit"
                aria-label={isDarkMode ? 'Light mode' : 'Dark mode'}
                startIcon={isDarkMode ? <LightModeIcon /> : <DarkModeIcon />}
                onClick={toggleThemeMode}
              >
                {isDarkMode ? 'Light mode' : 'Dark mode'}
              </Button>
              <Button size="small" color="inherit" startIcon={<LogoutIcon />} onClick={() => logout({ redirectTo: '/login' })}>
                Logout
              </Button>
            </Stack>
          </Toolbar>
        </AppBar>
        <Box sx={{ flex: '0 0 auto', px: APP_CONTENT_GUTTER, pt: { xs: 2, md: 2.5 }, pb: 1.5 }}>
          {breadcrumbs.length > 0 ? (
            <Stack direction="row" spacing={0.75} alignItems="center" flexWrap="wrap" useFlexGap sx={{ mb: 1 }} aria-label="Breadcrumb">
              {breadcrumbs.map((crumb, index) => (
                <React.Fragment key={`${crumb.label}-${index}`}>
                  {index > 0 ? <Typography variant="body2" color="text.secondary">/</Typography> : null}
                  {crumb.onClick ? (
                    <Button size="small" onClick={crumb.onClick} sx={{ minWidth: 0, px: 0.5 }}>{crumb.label}</Button>
                  ) : (
                    <Typography variant="body2" color="text.secondary">{crumb.label}</Typography>
                  )}
                </React.Fragment>
              ))}
            </Stack>
          ) : null}
          <Typography component="h1" variant="h4" sx={{ fontWeight: 700, fontSize: { xs: '1.5rem', md: '2rem' }, overflowWrap: 'anywhere' }}>
            {title}
          </Typography>
          {subtitle ? (
            <Typography variant="body1" color="text.secondary" sx={{ mt: 0.5, maxWidth: 760 }}>
              {subtitle}
            </Typography>
          ) : null}
        </Box>
        <Box component="main" sx={{ flex: 1, minWidth: 0, minHeight: 0, px: APP_CONTENT_GUTTER, pb: { xs: 2, md: 3 }, overflow: 'auto' }}>
          {children}
        </Box>
      </Box>
    </Box>
  );
};

export default ExpertPortalLayout;
